mapper.select:
select count(1)
from cf_checkin
where student_id = #{studentId}
  and create_time between #{startTime} and #{endTime}
  and (del_flag is null or del_flag = '0')

mapper.update:
update cf_checkin
student_id = #{studentId}, avatar = #{avatar}, push_flag = #{pushFlag}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id}
